#!/usr/bin/env python3# -*- coding: utf-8 -*-"""Created on Sat Jan 10 13:47:02 2026@author: anonymous"""# app/main.pyfrom contextlib import asynccontextmanagerfrom fastapi import FastAPIfrom app.db.base import Basefrom app.db.session import enginefrom app.db import modelsfrom app.api.health import router as health_routerfrom app.api.whatsapp import router as whatsapp_router@asynccontextmanagerasync def lifespan(app: FastAPI):    # Startup    Base.metadata.create_all(bind=engine)    yield    # Shutdown (nothing for now)app = FastAPI(    title="Society Event Management Agent",    lifespan=lifespan)# Routesapp.include_router(health_router)app.include_router(whatsapp_router)